    if total == 0:
        return None

    value = (thereafter / total) * 100
    return {
        "value": value,
        "trace": {
            "thereafter_maturities": thereafter,
            "total_scheduled_maturities": total,
            "ratio": thereafter / total,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage",
            },
        },
    }

def compute(vars):
    x0 = vars["100"]
    x1 = vars["Resulting Number"]
    x2 = vars["Starting Number"]

    if x2 == 0:
        return None

    percentage_change = x0 * (x1 - x2) / x2

    return {
        "value": percentage_change,
        "trace": {
            "x0": x0,
            "x1": x1,
            "x2": x2,
            "Resulting Number": x1,
            "Starting Number": x2,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }

def compute(vars):
    comparison_year_value = vars["Comparison Year Value"]
    base_year_value = vars["Base Year Value"]
    multiplier = 100.0

    if comparison_year_value is None or base_year_value is None:
        return None
    if base_year_value == 0:
        return None

    percentage_change = (
        (comparison_year_value - base_year_value) / base_year_value * multiplier
    )

    return {
        "value": percentage_change,
        "trace": {
            "Comparison Year Value": comparison_year_value,
            "Base Year Value": base_year_value,
            "100": multiplier,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage",
            },
        },
    }

